"""Parser tests. STEP inputs are generated by tests/step_samples.py."""

from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

import pytest
from tests.step_samples import (
    write_blind_hole,
    write_box,
    write_cube,
    write_cylinder,
    write_cylinder_along_x,
    write_plate_with_hole,
    write_sphere,
    write_two_boxes,
)

from step2revit import StepParseError, parse_step
from step2revit.document import validate_neutral_document
from step2revit.geom import profile_axes
from step2revit.parse import _UnitError, single_length_unit

ROOT = Path(__file__).resolve().parents[1]


def test_cylinder_matches_the_shank_box(tmp_path: Path) -> None:
    step = write_cylinder(tmp_path / "shank.step")
    output = tmp_path / "shank.json"
    document = parse_step(step, output)

    _assert_contract(document, step)
    assert document["source"]["length_unit"] == "millimetre"
    assert document["bounding_box"]["min"] == pytest.approx([-5, -5, 0], abs=1e-3)
    assert document["bounding_box"]["max"] == pytest.approx([5, 5, 40], abs=1e-3)
    assert document["extents"] == pytest.approx({"x": 10, "y": 10, "z": 40}, abs=1e-3)
    assert [solid["id"] for solid in document["solids"]] == ["solid_1"]

    feature = _only(document, "cylinder")
    assert feature["id"] == "cylinder_1"
    assert feature["solid_id"] == "solid_1"
    assert feature["origin"] == pytest.approx([0, 0, 0], abs=1e-3)
    assert feature["axis"] == pytest.approx([0, 0, 1], abs=1e-6)
    assert _size(document, feature["diameter"]) == pytest.approx(10, abs=1e-3)
    assert _size(document, feature["length"]) == pytest.approx(40, abs=1e-3)
    assert [item["name"] for item in document["parameters"]] == [
        "Cylinder1Diameter",
        "Cylinder1Length",
    ]

    written = json.loads(output.read_text(encoding="utf-8"))
    assert written == document
    assert output.read_bytes().endswith(b"\n")


def test_cylinder_along_x_keeps_step_axes(tmp_path: Path) -> None:
    step = write_cylinder_along_x(tmp_path / "pin.step")
    document = parse_step(step)
    feature = _only(document, "cylinder")
    assert feature["origin"] == pytest.approx([0, 0, 0], abs=1e-3)
    assert feature["axis"] == pytest.approx([1, 0, 0], abs=1e-6)
    assert _size(document, feature["diameter"]) == pytest.approx(10, abs=1e-3)
    assert _size(document, feature["length"]) == pytest.approx(40, abs=1e-3)
    assert document["bounding_box"]["min"] == pytest.approx([0, -5, -5], abs=1e-3)
    assert document["bounding_box"]["max"] == pytest.approx([40, 5, 5], abs=1e-3)


def test_box_is_a_short_extrusion(tmp_path: Path) -> None:
    step = write_box(tmp_path / "box.step")
    document = parse_step(step)
    _assert_contract(document, step)
    feature = _only(document, "extrusion")
    assert feature["axis"] == pytest.approx([1, 0, 0], abs=1e-6)
    assert feature["origin"] == pytest.approx([0, 10, 15], abs=1e-3)
    assert _size(document, feature["length"]) == pytest.approx(10, abs=1e-3)
    assert document["extents"] == pytest.approx({"x": 10, "y": 20, "z": 30}, abs=1e-3)
    _assert_profile_rebuilds_box(feature, document)


def test_cube_prefers_the_z_axis(tmp_path: Path) -> None:
    step = write_cube(tmp_path / "cube.step")
    document = parse_step(step)
    feature = _only(document, "extrusion")
    assert feature["axis"] == pytest.approx([0, 0, 1], abs=1e-6)
    assert feature["origin"] == pytest.approx([5, 5, 0], abs=1e-3)
    assert _size(document, feature["length"]) == pytest.approx(10, abs=1e-3)
    _assert_profile_rebuilds_box(feature, document)


def test_plate_with_hole(tmp_path: Path) -> None:
    step = write_plate_with_hole(tmp_path / "plate.stp")
    document = parse_step(step)
    _assert_contract(document, step)
    assert document["source"]["filename"] == "plate.stp"
    extrusion = _only(document, "extrusion")
    hole = _only(document, "hole")
    assert extrusion["axis"] == pytest.approx([0, 0, 1], abs=1e-6)
    assert extrusion["origin"] == pytest.approx([20, 15, 0], abs=1e-3)
    assert _size(document, extrusion["length"]) == pytest.approx(5, abs=1e-3)
    assert hole["origin"] == pytest.approx([20, 15, 0], abs=1e-3)
    assert hole["axis"] == pytest.approx([0, 0, 1], abs=1e-6)
    assert hole["through"] is True
    assert _size(document, hole["diameter"]) == pytest.approx(8, abs=1e-3)
    assert _size(document, hole["depth"]) == pytest.approx(5, abs=1e-3)
    assert document["bounding_box"]["min"] == pytest.approx([0, 0, 0], abs=1e-3)
    assert document["bounding_box"]["max"] == pytest.approx([40, 30, 5], abs=1e-3)
    _assert_profile_rebuilds_box(extrusion, document)
    names = {item["name"] for item in document["parameters"]}
    assert names == {"Extrusion1Length", "Hole1Diameter", "Hole1Depth"}


def test_blind_hole_points_into_the_material(tmp_path: Path) -> None:
    step = write_blind_hole(tmp_path / "blind.step")
    document = parse_step(step)
    hole = _only(document, "hole")
    assert hole["through"] is False
    assert hole["origin"] == pytest.approx([10, 10, 10], abs=1e-3)
    assert hole["axis"] == pytest.approx([0, 0, -1], abs=1e-6)
    assert _size(document, hole["diameter"]) == pytest.approx(6, abs=1e-3)
    assert _size(document, hole["depth"]) == pytest.approx(6, abs=1e-3)


def test_multi_solid_part_unions_the_boxes(tmp_path: Path) -> None:
    step = write_two_boxes(tmp_path / "pair.step")
    document = parse_step(step)
    _assert_contract(document, step)
    assert [solid["id"] for solid in document["solids"]] == ["solid_1", "solid_2"]
    assert document["bounding_box"]["min"] == pytest.approx([0, 0, 0], abs=1e-3)
    assert document["bounding_box"]["max"] == pytest.approx([25, 10, 10], abs=1e-3)
    extrusions = [
        feature for feature in document["features"] if feature["type"] == "extrusion"
    ]
    assert {feature["solid_id"] for feature in extrusions} == {"solid_1", "solid_2"}
    assert len(extrusions) == 2


def test_metre_and_inch_files_are_converted_to_millimetres(tmp_path: Path) -> None:
    metre = write_box(tmp_path / "metre.step", unit="M")
    inch = write_box(tmp_path / "inch.STEP", unit="INCH", schema="AP203")
    ap242 = write_box(tmp_path / "ap242.step", schema="AP242DIS")

    metre_document = parse_step(metre)
    inch_document = parse_step(inch)
    ap242_document = parse_step(ap242)
    for document in (metre_document, inch_document, ap242_document):
        assert document["units"]["length"] == "mm"
        assert document["extents"] == pytest.approx(
            {"x": 10, "y": 20, "z": 30}, abs=1e-3
        )
    assert metre_document["source"]["length_unit"] == "metre"
    assert inch_document["source"]["length_unit"] == "INCH"
    assert ap242_document["source"]["length_unit"] == "millimetre"


def test_missing_and_rejected_inputs_do_not_write(tmp_path: Path) -> None:
    output = tmp_path / "out.json"
    output.write_text("keep\n", encoding="utf-8")
    missing = tmp_path / "missing.step"
    with pytest.raises(StepParseError, match="missing.step") as missing_error:
        parse_step(missing, output)
    assert "does not exist" in missing_error.value.reason

    wrong_suffix = tmp_path / "part.txt"
    wrong_suffix.write_text("ISO-10303-21;", encoding="utf-8")
    with pytest.raises(StepParseError, match="part.txt") as suffix_error:
        parse_step(wrong_suffix, output)
    assert "must end in .step or .stp" in suffix_error.value.reason

    not_step = tmp_path / "notes.step"
    not_step.write_text("hello\n", encoding="utf-8")
    with pytest.raises(StepParseError, match="not a STEP physical file") as raised:
        parse_step(not_step, output)
    assert "notes.step" in str(raised.value)

    wrong_schema = tmp_path / "cnc.step"
    wrong_schema.write_text(
        "ISO-10303-21;\nHEADER;\nFILE_SCHEMA(('INTEGRATED_CNC_SCHEMA'));\n"
        "ENDSEC;\nDATA;\nENDSEC;\nEND-ISO-10303-21;\n",
        encoding="utf-8",
    )
    with pytest.raises(StepParseError, match="INTEGRATED_CNC_SCHEMA"):
        parse_step(wrong_schema, output)

    directory = tmp_path / "dir.step"
    directory.mkdir()
    with pytest.raises(StepParseError, match="not a file"):
        parse_step(directory, output)

    assert output.read_text(encoding="utf-8") == "keep\n"


def test_no_solids_and_no_features_do_not_write(tmp_path: Path) -> None:
    output = tmp_path / "out.json"
    output.write_text("keep\n", encoding="utf-8")
    empty = tmp_path / "empty.step"
    empty.write_text(
        "ISO-10303-21;\nHEADER;\n"
        "FILE_DESCRIPTION(('test'),'2;1');\n"
        "FILE_NAME('empty.step','2026-11-12T00:00:00',(''),(''),'','','');\n"
        "FILE_SCHEMA(('CONFIG_CONTROL_DESIGN'));\n"
        "ENDSEC;\nDATA;\nENDSEC;\nEND-ISO-10303-21;\n",
        encoding="utf-8",
    )
    with pytest.raises(StepParseError, match="no solids were found") as empty_error:
        parse_step(empty, output)
    assert "empty.step" in str(empty_error.value)

    sphere = write_sphere(tmp_path / "sphere.step")
    with pytest.raises(StepParseError, match="no supported features were found"):
        parse_step(sphere, output)
    assert output.read_text(encoding="utf-8") == "keep\n"


def test_unknown_length_unit_names(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    with pytest.raises(_UnitError):
        single_length_unit([])
    with pytest.raises(_UnitError):
        single_length_unit(["metre", "INCH"])
    assert single_length_unit(["millimetre", "millimetre"]) == "millimetre"

    step = write_box(tmp_path / "box.step")
    output = tmp_path / "out.json"
    output.write_text("keep\n", encoding="utf-8")

    def _unknown(_reader: object) -> str:
        raise _UnitError

    monkeypatch.setattr("step2revit.parse._length_unit", _unknown)
    with pytest.raises(StepParseError, match="the length unit is unknown") as error:
        parse_step(step, output)
    assert "box.step" in str(error.value)
    assert output.read_text(encoding="utf-8") == "keep\n"


def test_command_line(tmp_path: Path) -> None:
    step = write_cylinder(tmp_path / "shank.step")
    output = tmp_path / "shank.json"
    completed = subprocess.run(
        [sys.executable, "-m", "step2revit", str(step), str(output)],
        cwd=ROOT,
        capture_output=True,
        text=True,
        check=False,
    )
    assert completed.returncode == 0, completed.stderr
    assert json.loads(output.read_text(encoding="utf-8"))["schema_version"] == "1"

    failed = subprocess.run(
        [
            sys.executable,
            "-m",
            "step2revit",
            str(tmp_path / "missing.step"),
            str(output),
        ],
        cwd=ROOT,
        capture_output=True,
        text=True,
        check=False,
    )
    assert failed.returncode == 1
    assert "does not exist" in failed.stderr


def _assert_contract(document: dict, step: Path) -> None:
    validate_neutral_document(document)
    assert document["schema_version"] == "1"
    assert document["units"]["length"] == "mm"
    assert document["source"]["filename"] == step.name
    assert document["source"]["format"] == "STEP"
    box = document["bounding_box"]
    for index, axis_name in enumerate("xyz"):
        span = box["max"][index] - box["min"][index]
        assert document["extents"][axis_name] == pytest.approx(span, abs=1e-3)


def _only(document: dict, feature_type: str) -> dict:
    matches = [
        feature for feature in document["features"] if feature["type"] == feature_type
    ]
    assert len(matches) == 1
    return matches[0]


def _size(document: dict, reference: dict) -> float:
    name = reference["parameter"]
    values = [item["value"] for item in document["parameters"] if item["name"] == name]
    assert len(values) == 1
    return values[0]


def _assert_profile_rebuilds_box(feature: dict, document: dict) -> None:
    origin = feature["origin"]
    axis = feature["axis"]
    length = _size(document, feature["length"])
    profile_u, profile_v = profile_axes(axis)
    corners = []
    for u_coord, v_coord in feature["profile"]:
        start = [
            origin[index] + u_coord * profile_u[index] + v_coord * profile_v[index]
            for index in range(3)
        ]
        end = [start[index] + length * axis[index] for index in range(3)]
        corners.extend((start, end))
    rebuilt_min = [min(point[index] for point in corners) for index in range(3)]
    rebuilt_max = [max(point[index] for point in corners) for index in range(3)]
    assert rebuilt_min == pytest.approx(document["bounding_box"]["min"], abs=1e-3)
    assert rebuilt_max == pytest.approx(document["bounding_box"]["max"], abs=1e-3)
